  return { beat_id: 'b' + String(index + 1).padStart(2, '0'), role: index === 0 ? 'hook' : index === response.segments.length - 1 ? 'conclusion' : 'development', story_id: null, spoken_text: segment.text, supporting_fact_ids: [], voice: { emotion: 'Performance-directed', delivery_notes: '', fish_tags }, avatar: { asset_id, change_anchor, reason: 'Performance Director V3.1 event.' }, visuals: [], caption_emphasis: [] };
